-- 034: Mk5 GTI (FSI + TSI) — dogbone (pendulum) mount guide and the chaptered engine & transmission mount guide, both in 'Bushings & mounts'.
-- Task rows first (guides.id has a foreign key to tasks.id). Both engines share each guide.
-- Requires the App.jsx from update-033 (questions can now depend on an earlier answer) — deploy it before or with this SQL.
-- Upload the five SVGs in illustrations/ to the 'illustrations' Storage bucket after running this:
--   dogbone-hero.svg, dogbone-insert.svg, engine-mounts-hero.svg, engine-mount-detail.svg, trans-mount-detail.svg
begin;
insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('dogbone-mount','bpy','dogbone-mount','Dogbone (pendulum) mount: replace or upgrade','Bushings & mounts','mounts',array['dogbone','pendulum mount','torque arm','dogbone insert','wheel hop','clunk']::text[],true,'40 min–1 hr',2) on conflict (id) do update set powertrain_id=excluded.powertrain_id, guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('dogbone-mount-tsi','ccta','dogbone-mount','Dogbone (pendulum) mount: replace or upgrade','Bushings & mounts','mounts',array['dogbone','pendulum mount','torque arm','dogbone insert','wheel hop','clunk']::text[],true,'40 min–1 hr',2) on conflict (id) do update set powertrain_id=excluded.powertrain_id, guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('engine-trans-mounts','bpy','engine-trans-mounts','Engine & transmission mounts: replace or upgrade','Bushings & mounts','mounts',array['engine mount','motor mount','transmission mount','trans mount','hydraulic mount','idle vibration','034','BFI','VF Engineering']::text[],true,'2.5–3 hr',3) on conflict (id) do update set powertrain_id=excluded.powertrain_id, guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('engine-trans-mounts-tsi','ccta','engine-trans-mounts','Engine & transmission mounts: replace or upgrade','Bushings & mounts','mounts',array['engine mount','motor mount','transmission mount','trans mount','hydraulic mount','idle vibration','034','BFI','VF Engineering']::text[],true,'2.5–3 hr',3) on conflict (id) do update set powertrain_id=excluded.powertrain_id, guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into guides (id,content) values ('dogbone-mount',$j${"id": "dogbone-mount", "title": "Dogbone (pendulum) mount: replace or upgrade", "heroId": "dogbone-hero", "fits": "2006–2009 VW GTI · 2.0T FSI (BPY) and 2.0T TSI (CCTA/CBFA)", "alsoFits": "Mk5 Rabbit/Jetta 2.5 · Mk6 GTI/Golf/Jetta · Audi A3 8P · TT Mk2 (same PQ35 arm; inserts split early/late)", "category": "Bushings & mounts", "kind": "upgrade", "variants": {"questions": [{"question": "New factory mount, or an upgrade?", "hint": "The dogbone (VW calls it the torque arm; the manuals say pendulum mount) is the cast arm from the bottom of the transmission to the front subframe. Its big rubber bushing lives in the subframe and is soft on purpose. A factory replacement restores quiet; an upgrade fills or replaces the soft rubber to stop the drivetrain rocking.", "options": [{"id": "oe", "label": "Factory replacement", "when": "Bushing torn or collapsed, clunk over bumps, keep it stock-quiet"}, {"id": "upgrade", "label": "Upgrade", "when": "Clunk on and off the throttle, wheel hop, vague shifts on a mount that isn't actually broken"}]}, {"only": ["upgrade"], "question": "Which kind of upgrade?", "hint": "An insert fills the voids in the factory subframe bushing and takes half an hour with one bolt out. A full aftermarket mount replaces the whole arm, usually with a spherical bearing, and takes every bolt out. Inserts are cheaper and quieter; full mounts last longer and move less.", "options": [{"id": "insert", "label": "Insert into the factory bushing", "when": "034 billet, BFI Stage 1 or 2, ECS urethane · 30–40 min"}, {"id": "full", "label": "Full aftermarket mount", "when": "034 Billet Dogbone, ECS pendulum mount, VF Engineering (FSI only) · 1 hr"}]}]}, "glance": {"timeFirst": "40 min (insert) · 1 hr (mount swap)", "timeRepeat": "25 min (insert) · 45 min (swap)", "difficulty": 2, "cost": "$40–100 (insert) · $60–130 (OE mount + bolts) · $150–300 (billet mount)", "risk": "Car on stands · one M14 stretch bolt and two M10s, single-use · transmission-case threads strip", "why": "Under acceleration the engine tries to rotate backwards; on lift-off it snaps forward. The dogbone is what stops it, through one soft, voided rubber bushing in the subframe. New, it's quiet. Tired or asked to hold a tuned car, it lets the whole drivetrain rock, and you feel that as a clunk when you get on or off the gas, hop off the line, and shifts that never feel quite sure. It's the first mount most Mk5 owners touch because it's the easiest and the one you feel most.", "note": "Procedure from ECS Tuning's Mk5/Mk6 mount PDF, cross-checked against 034Motorsport's insert and billet-mount sheets and the ECS insert sheet. They agree on every step and on the M14 torque; 034's early-insert sheet is the one that leaves off the 90° turn."}, "heroCap": "From below: the arm runs from the bottom of the transmission case forward into the subframe. The 21 mm-head M14 bolt at the subframe goes through the big voided bushing; the two 16 mm-head M10 bolts go into the transmission case, one through the arm's small-end bushing and one through the front bracket.", "lifespan": {"title": "When to expect it", "headline": ["No factory interval. Owners replace or upgrade on symptoms, usually the first mount they touch"], "earliest": "Tuned cars and hard launches wear the voided bushing well before 100,000 miles", "detail": "The rubber doesn't wear like a pad; it tears or sags. The signs are a clunk from under the front on throttle transitions, a shudder on lift-off in first or second, and wheel hop off the line. Because this is the mount that takes the torque reaction, it goes first on a tuned car, and its condition decides how much noise the other two mounts transmit: 034 warns that new engine mounts feel harsher if the dogbone is worn.", "factors": ["Stage 1+ software", "Launches and clutch dumps", "Original bushing at high mileage", "Stripped or previously repaired transmission-case threads (loose mount)"], "inspect": ["Car on stands, grab the arm and pull it fore and aft. Movement you can see is a bushing that's done.", "Look at the two transmission-case bolt holes for pulled threads or a backed-out helicoil (ECS says it's common)."], "confidence": {"level": "community", "n": 4, "note": "ECS, 034 and BFI product notes plus forum experience; no factory interval exists."}}, "should": {"yesIf": ["Clunk from under the front when you get on or off the throttle", "Wheel hop off the line, especially on a tuned car", "Shifts feel vague and the shifter moves with the engine", "You're doing the engine and transmission mounts and want the set to match", "The bushing is visibly torn or the arm moves by hand"], "codes": [], "notes": ["Insert or full mount? Inserts (034 billet, BFI Stage 1 or 2, ECS urethane) fill the voids in the factory bushing and keep the factory mount; half an hour, one bolt, mild NVH. Full mounts (034 Billet Dogbone, ECS pendulum mount, VF Engineering) replace the arm with a spherical or firm bushing; more work, more noise, and they don't depend on rubber that's already aging.", "Inserts come in two shapes for the Mk5: early (cars built to about mid-2008; every FSI GTI) and late (2009 on, and the Mk6). 034 sells them as two part numbers, BFI asks for your model year. A 2008.5–2009 TSI is usually late, but confirm by build date on the door-jamb sticker before ordering.", "VF Engineering's lower mount fits the 2.0T FSI only; the seller's note says not the 2.5 or the 2009+ TSI.", "Whatever you fit, the M14 subframe bolt and the two M10 transmission bolts are stretch bolts. Buy the kit (ECS assembles one) unless your aftermarket mount supplies its own."], "confidence": {"level": "high", "n": 5, "note": "Sources agree on the job. The early/late insert split is from 034's two part numbers and BFI's model-year selector."}}, "parts": [{"tier": "oe", "name": "Dogbone (pendulum) mount, Genuine VW", "pn": "1K0 199 855 BJ (or BF · VIN-specific; supersedes AE/AN/BB/L)", "note": "Cast arm with both bushings. Stock hardness.", "price": "$50–100", "links": [{"store": "Europa Parts (Genuine)", "url": "https://www.europaparts.com/dogbone-mount-1k0199855bf.html"}], "only": ["oe"]}, {"tier": "oem", "name": "Dogbone mount, Lemförder", "pn": "cross to 1K0 199 855 BJ", "note": "Same part in the maker's box.", "price": "$40–70", "links": [{"store": "UroTuning (OE-fit)", "url": "https://www.urotuning.com/products/engine-dogbone-mount-rear-vw-audi-mk5-mk6-2-0t-2-5l-tdi-1k0199855bb-aft"}], "only": ["oe"]}, {"tier": "oe", "name": "Dogbone stretch-bolt kit: M14 subframe + 2× M10 transmission", "pn": "1K0 199 855 BB KT (ECS-assembled)", "note": "All three are single-use. Pelican quotes the set at under $10.", "price": "$10–20", "links": [{"store": "ECS Tuning", "url": "https://www.ecstuning.com/b-assembled-by-ecs-parts/dogbone-mount-hardware-kit/1k0199855bbkt/"}], "only": ["oe", "full"]}, {"tier": "aftermarket", "name": "034Motorsport billet dogbone insert, early Mk5 (to 2008.5)", "pn": "034-509-1020", "note": "Aluminium, fills the voids; 034 logo faces forward. Reuses the factory bolt. For every FSI GTI.", "price": "$40–60", "links": [], "only": ["insert"]}, {"tier": "aftermarket", "name": "034Motorsport billet dogbone insert, late Mk5/Mk6 (2009 on)", "pn": "034-509-1021", "note": "Same idea, later bushing shape. For most TSI cars; confirm build date.", "price": "$40–60", "links": [], "only": ["insert"]}, {"tier": "aftermarket", "name": "BFI torque arm insert, Stage 1 or Stage 2", "pn": "choose model year at checkout", "note": "Polyurethane. Stage 1 is the comfort version; Stage 2 is 90A and the stiffest on the market by BFI's description. Expect some vibration in reverse and at idle with A/C for the first ~1,000 miles.", "price": "$40–70", "links": [{"store": "BFI (Stage 1, 2009+)", "url": "https://blackforestindustries.com/products/bfi-stage-1-torque-arm-insert-dogbone-insert-2009"}, {"store": "BFI (Stage 2, 2009+)", "url": "https://blackforestindustries.com/products/bfi-stage-2-torque-arm-insert-dogbone-insert-2009"}], "only": ["insert"]}, {"tier": "aftermarket", "name": "ECS urethane dogbone insert", "pn": "ECS Mk5 dogbone insert kit", "note": "Urethane plug plus washer and a new 22 mm-head bolt. Grease it; it's a tight fit.", "price": "$40–60", "links": [], "only": ["insert"]}, {"tier": "aftermarket", "name": "034Motorsport Billet Dogbone Mount (spherical)", "pn": "034-509-1016", "note": "Billet arm with a spherical bearing; ships with M10×75 and M10×35 bolts and a spacer. 034 wants blue Loctite on everything.", "price": "$200–260", "links": [], "only": ["full"]}, {"tier": "aftermarket", "name": "ECS billet pendulum mount (Teflon-lined spherical)", "pn": "ECS Mk5/Mk6 pendulum mount", "note": "Sealed spherical with rubber boots; uses factory torque values with the new bolts.", "price": "$150–250", "links": [], "only": ["full"]}, {"tier": "aftermarket", "name": "VF Engineering lower dogbone mount", "pn": "VFA06-01", "note": "2.0T FSI only: the seller's note says it does not fit the 2.5 or the 2009+ TSI. Firm bushing, own hardware.", "price": "$150–200", "links": [{"store": "UroTuning", "url": "https://urotuning.com/products/vfa06-01"}], "only": ["full"]}], "aftermarket": [{"name": "Powerflex dogbone bushing inserts (65 / 70 / 80 durometer)", "note": "Three stiffnesses of the same idea as the BFI insert. Forum guide lists them; pick by how much cabin buzz you'll tolerate.", "price": "$40–70", "signal": "Community pick for a softer insert", "links": [], "only": ["insert", "oe"]}, {"name": "Torque Solution pendulum mount", "note": "Another full replacement arm for Mk5/Mk6 and A3 8P; less documentation than 034 or ECS.", "price": "$150–250", "signal": "Fewer install write-ups", "links": [], "only": ["full", "oe"]}, {"name": "034Motorsport Density Line dogbone mount pair (subframe bushings)", "note": "Not an insert and not an arm: these replace the two rubber bushings pressed into the subframe itself. The subframe has to come down and the old bushings pressed out. It's the front sway bar job with a press on top; not covered here.", "price": "$100–150 + a press", "signal": "Different job entirely", "links": []}], "tools": [{"name": "21mm and 16mm sockets, breaker bar, torque wrench to 100 Nm with an angle scale or a paint marker"}, {"name": "T25 and T30 Torx for the belly pan"}, {"name": "Pry bar to line the arm up with the transmission holes", "only": ["oe", "full"]}, {"name": "Grease for a urethane insert", "only": ["insert"]}, {"name": "Blue threadlocker", "note": "034 specifies it on every bolt of its billet mount", "only": ["full"]}, {"name": "Floor jack and two jack stands"}, {"name": "Thread repair kit (M10) on standby", "note": "ECS: transmission-case holes commonly strip", "only": ["oe", "full"]}], "before": ["Engine cool; the arm sits under the exhaust.", "Read the door-jamb build date if you're fitting an insert: early and late are different parts.", "Nothing needs supporting: the other two mounts hold the engine while the dogbone is out."], "steps": [{"n": 1, "title": "Find the arm and read its condition", "blocks": [{"t": "text", "b": "Car on stands, belly pan off (T25/T30). Under the front of the transmission you'll see the cast arm: its small end bolts into the transmission case with two 16 mm-head bolts (one through a small bushing in the arm, one through a front bracket), and its big end sits inside the subframe on a single 21 mm-head bolt through the big voided bushing. Grab the arm and pull fore and aft. Visible movement, a torn bushing, or an arm that's cracked means the mount itself; a firm but soft-feeling bushing with the clunk you came for is what an insert fixes."}, {"t": "ill", "id": "dogbone-hero", "cap": "Transmission at left, subframe at right. M14 through the subframe bushing; two M10s into the transmission case."}]}, {"n": 2, "title": "Insert: which one fits your car", "only": ["insert"], "blocks": [{"t": "text", "b": "Two bushing shapes were used. Cars built up to about mid-2008 (every FSI GTI) take the early insert; 2009-on cars and the Mk6 take the late one. 034 sells 034-509-1020 (early) and 034-509-1021 (late); BFI asks for the model year; ECS sells one urethane kit and tells you which cars. Read the build month on the door-jamb sticker before you order; a 2008.5 TSI can go either way."}, {"t": "ill", "id": "dogbone-insert", "cap": "Cross-section of the subframe bushing: rubber with two voids, and the insert filling the front void so the arm can't swing forward under load."}]}, {"n": 3, "title": "Insert: bolt out, insert in, bolt back", "only": ["insert"], "caution": true, "blocks": [{"t": "text", "b": "Remove the 21 mm-head bolt at the subframe completely (034, ECS). The arm stays on its two transmission bolts. A billet insert (034) simply drops into the void with its logo toward the front of the car; a urethane insert (ECS, BFI) is a tight fit: grease it and work it in until it's fully seated, then drop the washer into its centre. Refit the bolt: 034 reuses the factory bolt, ECS supplies a new 22 mm-head bolt."}, {"t": "torque", "label": "M14 dogbone-to-subframe bolt (21 mm, or ECS's 22 mm)", "nm": 100, "c": {"level": "varies", "n": 3, "note": "100 Nm + 90° per ECS (both sheets) and 034's late-insert sheet. 034's early-insert sheet says 100 Nm with no angle; the factory bolt is a stretch bolt, so we show the angle."}, "note": "+90° turn"}, {"t": "warn", "b": "That bolt is a stretch bolt. If you're refitting the factory one, ECS and VW would have you replace it; 034 reuses it for the insert. Either way, torque it once, mark it, and don't re-torque a stretched bolt later."}]}, {"n": 4, "title": "Mount swap: transmission bolts, then the big one", "only": ["oe", "full"], "caution": true, "blocks": [{"t": "text", "b": "Two 16 mm-head bolts into the transmission case first, then the 21 mm-head bolt at the subframe (ECS). The arm pulls forward out of the subframe. Before you go further, look hard at the two holes in the transmission case: ECS calls stripped threads here common, and their own demo car had a helicoil back out on the bolt. Loose, stubborn, or non-tightening bolts and missing threads all mean repair before the new mount goes on."}, {"t": "warn", "b": "Aluminium case, M10 stretch bolts. If a bolt turns without tightening, stop. A Time-Sert or helicoil now is cheap; a mount that walks loose at speed is not."}]}, {"n": 5, "title": "Mount swap: new arm in, small end first", "only": ["oe", "full"], "blocks": [{"t": "text", "b": "Slide the new arm into the subframe. Start the longer M10 through the arm's small-end bushing into the case and the shorter M10 through the front bracket, hand-tight, using a pry bar to walk the holes into line (034 and ECS both say the holes won't be lined up on their own). Then pull the arm rearward until the M14 drops through into the subframe bushing.", "only": ["oe", "full"]}, {"t": "note", "b": "034 Billet Dogbone: the spacer goes on top, between the spherical bearing and the transmission; the small bracket goes underneath; logo faces down. 034 supplies M10×75 (through the spherical) and M10×35 (front bracket) and wants blue threadlocker on all three bolts.", "only": ["full"]}, {"t": "note", "b": "ECS pendulum mount: cut the wire tie holding the brace to the mount and keep a finger on the sleeves, spacers and boots so they don't fall out; the bolt is what retains them.", "only": ["full"]}, {"t": "torque", "label": "M10 bolts into the transmission case (16 mm) ×2", "nm": 40, "alt": [45], "c": {"level": "varies", "n": 3, "note": "40 Nm + 90° for factory-style stretch bolts (ECS, both its own mount and the OE procedure). 034's kit uses its own 17 mm-head bolts at 45 Nm flat with Loctite. Torque the bolts you're holding to their own sheet."}, "note": "+90° with factory bolts"}, {"t": "torque", "label": "M14 dogbone-to-subframe bolt (21 mm)", "nm": 100, "c": {"level": "high", "n": 3, "note": "100 Nm + 90° (ECS pendulum mount sheet, ECS insert sheet, factory stretch bolt). 034 says 100 Nm flat on its billet mount with Loctite."}, "note": "+90° with the factory bolt"}]}, {"n": 6, "title": "First drive", "blocks": [{"t": "text", "b": "Belly pan on, car down, start it in gear with the brake on and watch the engine: it should barely move. Drive it and pay attention on throttle transitions; the clunk should be gone. Some new vibration at idle is normal with any upgrade, worst in reverse and with the A/C on (BFI), and it settles over the first several hundred miles. If the engine mounts are tired, a firm dogbone will make you notice them (034); that's the next guide in this category."}, {"t": "embed", "id": "LH7MhZvSklE", "title": "ECS Tuning: Mk5 dogbone mount installation", "note": "ECS's own video of the full-mount swap on a Mk5. Same bolts and order as the steps above."}]}], "alsoReplace": [{"name": "Engine and transmission mounts", "why": "If this one is tired, the hydraulic passenger mount usually is too, and 034 warns new mounts feel harsher against a worn dogbone. The combined guide is right beside this one."}, {"name": "Front sway bar or subframe collars", "why": "The subframe bolts are right there, and the dogbone comes off for both of those jobs anyway."}], "check": {"tab": "Read the old mount", "title": "What the old arm tells you", "illId": "dogbone-insert", "illCap": "The voided bushing is the part that ages; the cast arm almost never does.", "rows": [{"see": "Rubber cracked through, arm moves by hand", "means": "Mount was the clunk.", "do": "Factory mount or full aftermarket arm; an insert can't fill a bushing that's torn."}, {"see": "Rubber intact, voids clean", "means": "Mount was fine; the slop is design.", "do": "Insert is the right upgrade; keep the arm."}, {"see": "Bolt came out with aluminium on the threads, or spun without tightening", "means": "Transmission-case threads are damaged.", "do": "Time-Sert or helicoil before anything goes back on (ECS)."}, {"see": "Clunk still there after the job", "means": "Not the dogbone.", "do": "Check the engine and transmission mounts, then the front control-arm bushings and the sway bar end links."}], "c": {"level": "community", "n": 3, "note": "ECS install notes and forum experience; no factory inspection procedure."}}, "aftercare": ["Recheck the three bolts after the first few hundred miles if they weren't stretch bolts (034 billet with Loctite).", "Expect idle vibration to fade over ~1,000 miles with a poly insert (BFI).", "Note which insert (early or late) you fitted."], "disagreements": [{"topic": "Angle on the M14 bolt", "pos": "ECS: 100 Nm + 90° on both its sheets; 034 late insert: 100 Nm + 90°; 034 early insert and billet mount: 100 Nm flat (with Loctite on the mount).", "call": "Factory bolt gets the angle. 034's own hardware gets 034's number."}, {"topic": "Reuse the subframe bolt for an insert?", "pos": "034 reuses the factory bolt; ECS supplies a new one and VW treats it as single-use.", "call": "New bolt if you have one; it's a few dollars. If you reuse, don't re-torque it later."}, {"topic": "Insert or full mount?", "pos": "Vendors sell both; forum consensus is insert first on a street car, full mount on a tuned or tracked car or when the rubber is already gone.", "call": "Insert unless the bushing is torn or the car makes real torque."}], "sources": ["ECS Tuning, 'VW MK5/MK6 Engine, Trans and Pendulum Mount Installation Instructions' (2019): procedure, thread-damage warning, torque table", "ECS Tuning, 'MKV Dog Bone Insert Installation Instructions'", "034Motorsport, billet dogbone insert install guides for early Mk5 (034-509-1020) and 2009+ Mk5/Mk6 (034-509-1021)", "034Motorsport, Billet Dogbone Mount install guide (034-509-1016)", "034Motorsport, Density Line Dogbone Mount Pair install blog (why subframe bushings are a different job)", "BFI product pages: Stage 1 and Stage 2 torque arm inserts (2009–2014), Mk5/Mk6 mount kits (model-year selector)", "UroTuning listing for VF Engineering VFA06-01 (FSI-only fitment note)", "Europa Parts, UroTuning and Darkside listings for 1K0 199 855 BJ/BF supersessions", "Pelican Parts, 'Golf GTI Mk V Dog Bone Replacement' (bolt kit 1K0199855BBKT)", "VWVortex, 'The Official MkV Golf/Jetta Aftermarket Engine/Transmission Mount Guide' (Powerflex durometers, Autotech early-only note)"], "embeds": [{"id": "LH7MhZvSklE", "note": "ECS Tuning, 2011: Mk5 dogbone mount installation."}]}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now(), created_at=now();
insert into guides (id,content) values ('engine-trans-mounts',$j${"id": "engine-trans-mounts", "title": "Engine & transmission mounts: replace or upgrade", "heroId": "engine-mounts-hero", "fits": "2006–2009 VW GTI · 2.0T FSI (BPY) and 2.0T TSI (CCTA/CBFA)", "alsoFits": "Mk6 GTI/Golf/Jetta 2.0T · Audi A3 8P 2.0T (same mounts and torques per ECS; the 2.5 uses different mounts)", "category": "Bushings & mounts", "kind": "upgrade", "chapters": [{"id": "engine", "title": "Engine mount", "blurb": "Passenger side, between the front of the engine and the frame rail. Hydraulic from the factory."}, {"id": "trans", "title": "Transmission mount", "blurb": "Driver side, under the battery tray and the wiring channel. The longer of the two."}, {"id": "finish", "title": "Finish", "blurb": "Both mounts in, first start, and the break-in."}], "variants": {"questions": [{"question": "New factory mounts, or an upgrade?", "hint": "The passenger-side engine mount is fluid-filled and the driver-side transmission mount is voided rubber; both are tuned for quiet. A factory pair puts the car back to new. Upgrades trade some cabin vibration for an engine that stays put under throttle.", "options": [{"id": "oe", "label": "Factory replacement", "when": "Idle vibration, engine visibly rocking, oily film on the passenger mount, keep it quiet"}, {"id": "upgrade", "label": "Upgrade", "when": "Tuned car, wheel hop, shifter moving with the engine, or you're already in there"}]}, {"only": ["upgrade"], "question": "Which mounts?", "hint": "Every kit here bolts into the factory brackets. They differ in how stiff they are, how much they buzz, and whose bolts and torques you follow. Pick yours and the guide shows only that kit's hardware notes.", "options": [{"id": "density", "label": "034Motorsport Density Line (Street or Track)", "when": "Solid rubber, none-to-low NVH on Street; factory-style bolts", "brand": true}, {"id": "bfi", "label": "BFI Stage 1 or Stage 2", "when": "Complete polyurethane mounts, or the Stage 1 transmission insert; new factory bolts needed", "brand": true}, {"id": "vf", "label": "VF Engineering", "when": "Firm mounts with their own bolts and a 6 mm centre screw; re-torque at 200 miles", "brand": true}, {"id": "ecs", "label": "ECS Tuning billet / 70A poly", "when": "Billet bodies, poly bushings; ECS's own torque table (the one this guide uses)", "brand": true}, {"id": "other", "label": "Another brand or inserts", "when": "Powerflex or Vibra-Technics inserts, StreetSport billet, Neuspeed, APR"}]}]}, "glance": {"timeFirst": "1 hr engine · 1.5–2 hr transmission", "timeRepeat": "45 min · 1 hr", "difficulty": 3, "cost": "$150–300 (OE pair + bolts) · $250–600 (upgrade pair)", "risk": "Engine held on a floor jack · nine stretch bolts, single-use · battery out on the driver side", "why": "Three mounts hold the drivetrain: this pair carries its weight, the dogbone stops it rotating. The passenger mount is hydraulic; when its fluid leaves, the engine sits lower, idles rough through the steering wheel, and rocks on the throttle. The transmission mount is plain rubber and sags with it. Worn, they make everything from the shifter to the exhaust feel loose; upgraded, they make a tuned car put its power down and cost you some buzz at idle.", "note": "Procedure and every torque value from ECS Tuning's Mk5/Mk6 mount installation PDF, which is also the factory table. Pelican Parts' Mk5 article agrees on the bolts and adds the alignment check. Owner write-ups for VF Engineering supply that kit's numbers."}, "heroCap": "Looking down into the bay: engine mount on the passenger frame rail behind the coolant and washer reservoirs, transmission mount on the driver rail under the battery tray, dogbone below the front of the transmission.", "lifespan": {"title": "When to expect it", "headline": ["No factory interval. The hydraulic passenger mount is the one that fails; owners replace both together"], "earliest": "An oily film or drips on the passenger mount's body means the fluid is gone, whatever the mileage", "detail": "The engine mount is fluid-damped, and the fluid eventually finds a way out. When it does the mount collapses and the engine sits closer to the frame rail: Pelican's check is a minimum 10 mm gap between the engine and the rail. The transmission mount is solid rubber and simply softens. Symptoms are idle vibration you feel in the wheel and pedals, a lurch on throttle transitions, and an engine you can rock by hand (UroTuning's test: grab the top of the engine and shake it).", "factors": ["Oil leaks onto the passenger mount (valve cover, PCV)", "Tuned car or hard launches", "Original mounts at high mileage", "A worn dogbone letting the drivetrain rock into the mounts"], "inspect": ["Engine idling, hood up: watch the engine while a helper shifts between drive/reverse (or lets the clutch bite in gear). A jump is a mount.", "Look for a wet or oily body on the passenger mount, and for the engine sitting close to the frame rail."], "confidence": {"level": "community", "n": 4, "note": "Pelican's clearance figure and vendor symptom lists plus forum experience; no factory interval exists."}}, "should": {"yesIf": ["Idle vibration through the wheel and pedals that changes in gear", "Engine rocks visibly on throttle, or lurches on lift-off", "Oily residue on the passenger-side mount", "Shifter or exhaust moves with the engine; exhaust knocks on the tunnel", "Tuned car with wheel hop after the dogbone is already done"], "codes": [], "notes": ["Order of operations across the three mounts: do the dogbone first or at the same time. 034 notes that stiffer engine mounts transmit more NVH if the dogbone is worn, and a worn dogbone is what lets the engine hit the mounts hard in the first place.", "How stiff is stiff? 034's Street Density is 60-durometer rubber, about 35% stiffer than stock, and because it's void-free the mount works out around 60% stiffer, with none-to-low NVH by 034's own rating and a 250-mile break-in. Track Density and 034's StreetSport billet are for track cars and carry a medium-high NVH rating and a 1,000–2,000-mile break-in. BFI Stage 2 is 85–90A polyurethane, the stiffest street option; BFI says expect vibration in reverse and at idle with A/C for about 1,000 miles. VF Engineering owners describe idle buzz through the pedals that fades.", "Every one of the nine factory bolts is a stretch bolt. Genuine mount kits and 034 ship new ones; BFI's transmission insert does not (four N-905-969-06 and three N-105-524-02 from the dealer); VF supplies its own bolts and asks you not to reuse any factory ones."], "confidence": {"level": "high", "n": 5, "note": "ECS, Pelican and the VF write-ups agree on the procedure; stiffness and NVH figures are the makers' own."}}, "parts": [{"tier": "oe", "name": "Engine mount (passenger, hydraulic), Genuine VW / Lemförder", "pn": "1K0 199 262 M", "note": "Lemförder is the factory supplier. FCP's kit adds the bolts.", "price": "$70–150", "links": [{"store": "FCP Euro (Lemförder, with bolts)", "url": "https://www.fcpeuro.com/products/audi-vw-engine-mount-kit-lemforder-1k0199262m"}, {"store": "FCP Euro (OE supplier kit)", "url": "https://www.fcpeuro.com/products/vw-engine-mount-kit-oem-kit-1k0199262cbkt1"}], "only": ["oe"]}, {"tier": "oe", "name": "Transmission mount (driver), Genuine VW / Lemförder", "pn": "1K0 199 555 Q", "note": "Solid rubber. Buy the pair; they age together.", "price": "$60–120", "links": [{"store": "UroTuning (Lemförder pair)", "url": "https://www.urotuning.com/products/motor-mount-set-mk5-mk6-2-0t-lemforder-1k0199555q_1k0199262m"}], "only": ["oe"]}, {"tier": "oe", "name": "Stretch bolts: engine side 2× M12, 2× M10, 2× M8 · trans side 3× M12 (N 105 524 02), 4× M10 (N 905 969 06)", "pn": "per BFI's hardware list and ECS's torque table", "note": "Single-use, all nine. Genuine kits include theirs; check any aftermarket box before you start.", "price": "$20–40", "links": [], "only": ["oe", "bfi", "other", "density"]}, {"tier": "aftermarket", "name": "034Motorsport Density Line engine/transmission mount pair, Street or Track", "pn": "Mk5/Mk6 2.0T FSI/TSI pair", "note": "Void-free solid rubber in redesigned cast bodies; Street for daily cars, Track for track cars. 250-mile break-in.", "price": "$250–350", "links": [{"store": "034Motorsport", "url": "https://www.034motorsport.com/motorsport-streetsport-engine-transmission-mount-pair-mkv-mkvi-volkswagen-golf-jetta-gti-gli-8j-8p-audi-a3-tt-2-0t-billet-aluminum.html"}], "only": ["density"]}, {"tier": "aftermarket", "name": "BFI Stage 1 or Stage 2 mount kit, 4-cylinder 6-speed/DSG", "pn": "BFI Mk5/Mk6 engine mount kit (choose model year for the included torque-arm insert)", "note": "Complete replacement engine and transmission mounts plus a dogbone insert. Stage 1 for comfort, Stage 2 for stiffness.", "price": "$400–600", "links": [{"store": "BFI (Stage 1 kit)", "url": "https://blackforestindustries.com/products/bfi-mk5-mk6-engine-mount-kit-4-cylinder-stage-1"}], "only": ["bfi"]}, {"tier": "aftermarket", "name": "BFI Stage 1 transmission mount insert", "pn": "BFI Mk5/Mk6 OE trans mount insert", "note": "Poly insert into the factory transmission mount instead of a whole mount. New bolts not included: 4× N-905-969-06, 3× N-105-524-02.", "price": "$60–90", "links": [{"store": "BFI", "url": "https://blackforestindustries.com/products/bfi-mk5-mk6-stage-1-transmission-mount-insert"}], "only": ["bfi"]}, {"tier": "aftermarket", "name": "VF Engineering engine and transmission mounts", "pn": "VF Mk5 2.0T mounts", "note": "Own 15/16 mm-head bolts supplied; a 6 mm Allen centre screw on each mount. Owners' torques: 60 Nm to the engine/transmission, 40 Nm to the frame, 40 Nm centre; re-torque at 200 miles.", "price": "$300–450", "links": [], "only": ["vf"]}, {"tier": "aftermarket", "name": "ECS Tuning billet engine and transmission mounts (70A poly)", "pn": "ECS Mk5/Mk6 performance mounts", "note": "6061 billet bodies, 70A polyurethane bushings, anodised. The install PDF this guide follows is theirs.", "price": "$250–400", "links": [], "only": ["ecs"]}], "aftermarket": [{"name": "Powerflex engine and transmission mount inserts (65 / 80 durometer)", "note": "Poly inserts that go into the factory mounts, two stiffnesses each. Cheaper than whole mounts; the factory rubber stays, so they won't rescue a collapsed hydraulic mount.", "price": "$60–120", "signal": "Community pick for a mild upgrade on a healthy mount", "links": []}, {"name": "034Motorsport StreetSport billet mounts", "note": "Billet aluminium with replaceable Density Line rubber, lifetime guarantee at any power level. Medium-high NVH by 034's rating, 1,000–2,000-mile break-in. A track part.", "price": "$500–700", "signal": "Track cars", "links": []}, {"name": "Vibra-Technics, Neuspeed, APR", "note": "Listed for the Mk5 by UK and US retailers; less install documentation than the four kits above. Bolt pattern is factory, so the steps here apply.", "price": "$200–400", "signal": "Fewer write-ups", "links": []}], "tools": [{"name": "18mm, 16mm, 13mm and 10mm sockets; breaker bar; extensions"}, {"name": "Torque wrench to 60 Nm with an angle scale or paint marker"}, {"name": "T25 and T30 Torx (reservoir screws, belly pan)"}, {"name": "6mm Allen for the centre screw", "only": ["vf"]}, {"name": "Floor jack with a wood block or thick pad, two jack stands"}, {"name": "Pry bar to align bolt holes"}, {"name": "5mm Allen or T25 for the airbox, depending on your intake"}], "before": ["Engine cool. The engine mount sits under the coolant reservoir and you'll be lifting the reservoir aside without draining it (Pelican): keep it upright.", "Have the new bolts in hand and count them: two M12, two M10, two M8 on the engine side; three M12 and four M10 on the transmission side.", "Radio code and clock: the battery comes out for the transmission side."], "steps": [{"n": 1, "chapter": "engine", "title": "Clear the corner: washer spout, reservoir, side brace", "blocks": [{"t": "text", "b": "Passenger side. Unbolt the washer-fluid fill spout (10 mm) and pull it forward clear of the mount. Unplug the coolant level sensor, lift the wiring harness off the back of the reservoir, remove its two screws (T25 or Phillips) and hold the reservoir aside, upright, without disconnecting its hoses (ECS, Pelican). If you run a catch can on the mount stud, unbolt its bracket. Then the two side-brace bolts (13 mm) and lift the brace off."}, {"t": "ill", "id": "engine-mount-detail", "cap": "Passenger side, seen from the front. Two M12 bolts (18 mm) down into the engine bracket, two M10 bolts (16 mm) into the frame rail, the M8 side brace (13 mm) on top, and the jack under the end of the oil pan."}]}, {"n": 2, "chapter": "engine", "title": "Support the engine", "caution": true, "blocks": [{"t": "text", "b": "Car on stands, belly pan or insulation tray off (T25/T30). Floor jack with a wood block or a good rubber pad under the end of the oil pan, not the middle (ECS). Raise it only until it touches and takes the weight: you're supporting, not lifting. If the engine sags as the bolts loosen, pump the jack a little; when the jack is carrying the engine, the bolts unthread easily."}, {"t": "warn", "b": "Never put any part of you under an engine held only by a jack. Do everything from beside the car."}]}, {"n": 3, "chapter": "engine", "title": "Old mount out", "blocks": [{"t": "text", "b": "Ease the fuel lines aside and remove the two mount-to-engine-bracket bolts (18 mm, breaker bar), then the two mount-to-body bolts (16 mm). Lift the mount out. Look down into the frame channel: ECS says it's usually full of dirt and debris; clean it before the new mount goes in so the mount sits flat."}, {"t": "note", "b": "Pelican's article also pulls an 18 mm bolt through the access plug in the wheel well; that's for removing the engine bracket itself (timing belt job), not for a mount swap. You don't need it."}]}, {"n": 4, "chapter": "engine", "title": "New mount in, in this order", "caution": true, "blocks": [{"t": "text", "b": "Set the mount in. Start the two engine-bracket bolts by hand a few turns, then start the two body bolts. Now fully thread the body bolts to hand-tight first, then the bracket bolts (ECS). Raise or lower the jack a touch whenever a bolt starts to bind; if it feels tight going in, stop and move the jack. Before torquing, Pelican's check: the mount parallel to the bracket on both axes, and at least 10 mm between the engine and the frame rail."}, {"t": "torque", "label": "M12 mount-to-engine-bracket bolts (18 mm) ×2", "nm": 60, "c": {"level": "high", "n": 3, "note": "60 Nm + 90° (ECS torque table; factory value). VF's owner write-ups quote 60 Nm flat for VF's own bolts."}, "note": "+90° with factory-style bolts"}, {"t": "torque", "label": "M10 mount-to-body bolts (16 mm) ×2", "nm": 40, "c": {"level": "high", "n": 3, "note": "40 Nm + 90° (ECS). VF: 40 Nm flat with VF's bolts."}, "note": "+90° with factory-style bolts"}, {"t": "torque", "label": "M8 side brace bolts (13 mm) ×2", "nm": 20, "c": {"level": "high", "n": 2, "note": "20 Nm + 90° (ECS table)."}, "note": "+90° turn"}, {"t": "note", "b": "VF Engineering: no factory bolts are reused; tighten the supplied 15 and 16 mm-head bolts to 60 Nm at the engine and 40 Nm at the frame, and the 6 mm Allen centre screw to 40 Nm. Owners torque everything twice, then again after 200 miles.", "only": ["vf"]}, {"t": "note", "b": "BFI complete mount: new bolts come with the engine mount. The insert-style transmission piece is dealt with in the next chapter.", "only": ["bfi"]}, {"t": "note", "b": "Inserts (Powerflex and similar): the factory mount comes out as above, the insert is pressed into its voids on the bench, and the mount goes back in with new stretch bolts to the factory values shown.", "only": ["other"]}]}, {"n": 5, "chapter": "engine", "title": "Corner back together", "blocks": [{"t": "text", "b": "Side brace on and torqued, reservoir back on its two screws, harness clipped to it, level sensor plugged in, washer spout bolted. Catch-can bracket if you have one. Leave the jack and belly pan where they are if you're going straight on to the transmission side."}]}, {"n": 6, "chapter": "trans", "title": "Airbox and battery out", "blocks": [{"t": "text", "b": "Driver side. Airbox or intake off. Press the battery cover's release tab and lift it; lift the front half of the battery box off the rear half. Negative terminal first, then positive; tuck them aside. Battery hold-down (13 mm), battery out. Three tray bolts (10 mm); lift the rear of the tray, tilt it forward and guide its lower left stud around the relay-panel wiring (ECS). Pelican does the same: there's no way to the mount without the tray gone."}, {"t": "ill", "id": "trans-mount-detail", "cap": "Driver side with the battery tray gone: three M12 bolts (18 mm) into the transmission bracket, four M10 bolts (16 mm) into the rail under the lifted wiring channel, jack under the transmission case."}]}, {"n": 7, "chapter": "trans", "title": "Lift the wiring channel", "blocks": [{"t": "text", "b": "With the tray out you can see the three bolts into the transmission bracket, but the four body bolts hide under the plastic wiring-harness channel. Lift the channel up off its tabs and pull it aside (ECS, Pelican). One of the four body bolts is hidden even then; you'll find it by feel at the front."}]}, {"n": 8, "chapter": "trans", "title": "Support the transmission", "caution": true, "blocks": [{"t": "text", "b": "Jack with wood under the transmission case, raised only until it touches and takes the weight (ECS, Pelican). Same rule as the engine side: if the drivetrain drops as bolts loosen, pump the jack a little."}]}, {"n": 9, "chapter": "trans", "title": "Old mount out", "blocks": [{"t": "text", "b": "Three mount-to-transmission-bracket bolts (18 mm, breaker bar), then hold the wiring channel back and remove the four mount-to-body bolts (16 mm). Lowering the transmission slightly on the jack gives the room to slide the mount out (ECS). Inspect and clean the cradle on the frame channel."}]}, {"n": 10, "chapter": "trans", "title": "New mount in", "caution": true, "blocks": [{"t": "text", "b": "Set the new mount in. Four body bolts first, to torque; then the three bracket bolts, moving the jack a touch whenever one binds (ECS). This is the reverse of the engine side, and it matters: the body bolts locate the mount, the bracket bolts then pull the transmission to it."}, {"t": "torque", "label": "M10 mount-to-body bolts (16 mm) ×4", "nm": 40, "c": {"level": "high", "n": 3, "note": "40 Nm + 90° (ECS; factory). VF: 40 Nm flat with VF's bolts."}, "note": "+90° with factory-style bolts"}, {"t": "torque", "label": "M12 mount-to-transmission-bracket bolts (18 mm) ×3", "nm": 60, "c": {"level": "high", "n": 3, "note": "60 Nm + 90° (ECS; factory). VF owner write-up: 60 Nm."}, "note": "+90° with factory-style bolts"}, {"t": "note", "b": "VF Engineering: 60 Nm at the transmission, 40 Nm at the frame, 6 mm Allen centre screw 40 Nm, VF's bolts only. Torque twice, release the jack, and re-torque after 200 miles.", "only": ["vf"]}, {"t": "note", "b": "BFI Stage 1 transmission insert: the factory mount comes out as above, the poly insert goes into it on the bench, and it returns with new bolts: four N-905-969-06 to the body, three N-105-524-02 to the bracket. BFI doesn't include them.", "only": ["bfi"]}, {"t": "note", "b": "034 Density Line: factory-style stretch bolts to the factory values above. Give the mounts 250 miles before judging the NVH.", "only": ["density"]}]}, {"n": 11, "chapter": "trans", "title": "Back together", "blocks": [{"t": "text", "b": "Wiring channel back on its tabs (it may sit snug over a taller aftermarket mount: pull it up a little to clear), battery tray with its three bolts, battery in, positive first then negative, hold-down, box halves and cover, airbox. Jack out, belly pan on."}]}, {"n": 12, "chapter": "finish", "title": "First start and the break-in", "blocks": [{"t": "text", "b": "Hood up, start it, and watch the engine as a helper shifts between drive and reverse, or lets the clutch bite in gear with the brake on. It should barely move. Expect more vibration at idle than before with any upgrade: worst in reverse and with the A/C compressor on (BFI), fading over 250 miles (034 Street) to 1,000 miles (BFI, VF) or longer for track mounts. Re-check every bolt after the first drive, and at 200 miles if you fitted VF."}, {"t": "embed", "id": "4dRIaPAbbr4", "title": "Owner: Mk5 GTI engine and transmission mounts", "note": "A blown factory pair swapped on a Mk5; good look at both corners with the reservoirs and battery out."}, {"t": "embed", "id": "NVFeFbG1E_I", "title": "BFI: transmission mount install, Mk5/Mk6", "note": "BFI's own overview of the driver-side job with their complete mount."}]}], "alsoReplace": [{"name": "Dogbone (pendulum) mount", "why": "Do it first or with these. 034 warns a worn dogbone makes new engine mounts feel harsh, and it's the mount that lets the engine hit these two."}, {"name": "Battery hold-down and terminal clamps", "why": "You've got the battery out; a corroded clamp or a missing hold-down is a five-dollar fix while you're there."}, {"name": "PCV or valve-cover leak, if the passenger mount was oily", "why": "Oil kills mount rubber. Find where it came from or the new mount goes the same way."}], "check": {"tab": "Read the old mounts", "title": "What the old pair tells you", "illId": "engine-mount-detail", "illCap": "The passenger mount is the fluid-filled one; the driver mount is plain rubber.", "rows": [{"see": "Passenger mount wet or oily, engine sat close to the rail", "means": "Hydraulic mount had lost its fluid; that was your idle vibration.", "do": "Replace the pair. If the oil came from above, fix the leak too."}, {"see": "Rubber cracked or separated from the metal on either mount", "means": "Age.", "do": "Pair, plus the dogbone if it hasn't been done."}, {"see": "Both look fine but the engine rocked", "means": "The dogbone is the loose one.", "do": "Dogbone guide; these two can go back in."}, {"see": "Vibration worse after upgrade, doesn't fade in 1,000 miles", "means": "A bolt short of torque, an insert not fully seated, or a mount not sitting flat on a dirty cradle.", "do": "Re-check torque and seating; then accept that Track/Stage 2 mounts buzz."}], "c": {"level": "community", "n": 4, "note": "Pelican's clearance check, vendor break-in notes and forum experience."}}, "aftercare": ["Re-torque everything after the first drive; VF asks for 200 miles.", "Give upgrades their break-in before judging: 250 miles (034 Street) to 1,000+ (BFI Stage 2, VF, track mounts).", "If the passenger mount was oily, find the leak."], "disagreements": [{"topic": "Which side first?", "pos": "ECS does engine then transmission; Pelican the same; the VF owner did the pendulum, then engine, then transmission.", "call": "Engine, then transmission, with the dogbone done first or the same day."}, {"topic": "Angle or no angle?", "pos": "ECS and the factory table: every bolt is xx Nm + 90° and single-use. VF's owners: flat values with VF's non-stretch bolts, re-torqued at 200 miles.", "call": "Factory-style bolts get the angle and one use. VF bolts follow VF."}, {"topic": "Inserts or whole mounts?", "pos": "BFI and Powerflex sell inserts into the factory mounts; 034 and ECS sell whole mounts and say inserts still rely on old rubber.", "call": "Inserts only on a healthy mount. A collapsed hydraulic mount gets replaced."}, {"topic": "How much buzz?", "pos": "034 rates Street Density none-to-low; BFI warns of reverse and A/C idle vibration for 1,000 miles; VF owners report pedal buzz at idle that fades.", "call": "Street-rated rubber for a daily; poly or billet only if you want to feel it."}], "sources": ["ECS Tuning, 'VW MK5/MK6 Engine, Trans and Pendulum Mount Installation Instructions' (2019): full procedure, bolt sizes, torque table", "Pelican Parts, 'Golf GTI Mk V Engine Mount Replacement (2006–2009)': bolt sizes, reservoir handling, 10 mm engine-to-rail alignment check", "VWVortex, 'How To: VF Engineering transmission mount install' and 'engine passenger side mount install' (2008): VF torques, hardware, break-in", "034Motorsport product pages: Density Line Street/Track pair (durometer and stiffness figures, 250-mile break-in), StreetSport billet (NVH rating, break-in)", "BFI product pages: Mk5/Mk6 Stage 1 mount kit, Stage 1 transmission insert (hardware part numbers, vibration note)", "UroTuning and FCP Euro listings: 1K0 199 262 M and 1K0 199 555 Q (Lemförder), engine-to-rail shake test", "VWVortex, 'The Official MkV Golf/Jetta Aftermarket Engine/Transmission Mount Guide' (Powerflex, Vibra-Technics options)"], "embeds": [{"id": "4dRIaPAbbr4", "note": "Owner video, 2016: factory engine and transmission mounts on a Mk5 GTI."}, {"id": "NVFeFbG1E_I", "note": "BFI, 2016: performance transmission mount install, Mk5/Mk6."}]}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now(), created_at=now();
commit;
